from urllib.parse import urlparse, urlsplit, urlunsplit, quote
def _safe_url(url):
    """Adresteki boşluk ve Türkçe harfleri kodla (ör. '2027de neler olacak.wav')."""
    p = urlsplit(url)
    return urlunsplit((p.scheme, p.netloc, quote(p.path, safe="/%"), quote(p.query, safe="=&%"), p.fragment))


